# Six guides that feed the formulation cluster (exec'd from ext_50_resources.py, before the resources hub).
# General formulation science only. No recipe, no percentages beyond the listed grades, no cost figures.

_RL = [("/biostimulant-formulations", "Biostimulant formulations", "Ready-to-pack, private label, custom"), ("/start-biostimulant-business-india", "Start a biostimulant business", "Steps and models")]

# F1 -----------------------------------------------------------------
art("how-biostimulants-are-formulated", "How biostimulants are formulated: actives, base, pH and stability", "How Biostimulants Are Formulated: Actives, pH & Stability",
 "What goes into a finished biostimulant: the active, base, pH control and preservation, and why products with the same label percentage can differ.",
 "A biostimulant is formulated by combining an active ingredient, such as humic acid, seaweed extract or amino acid, with a base and other ingredients that keep it stable, mixable and safe to store. The active sets what the product is. The pH, preservation and carrier decide whether it stays clear, mixes in a tank and still performs at the end of its shelf life.",
 [("parts", "The parts of a formulation", table(["Part", "What it does", "Why it matters"], [
     ["Active", "Humic acid, seaweed extract, amino acid or protein hydrolysate", "Sets the grade and the concentration on the label"],
     ["Base or carrier", "Water for liquids, a carrier for powders and granules", "Affects handling, dose and cost per acre"],
     ["pH control", "Keeps the product in its stable range", "Humic acid dissolves at alkaline pH and settles out when it turns acidic"],
     ["Preservation", "Protects organic liquids from spoilage", "Seaweed and protein liquids can spoil if not protected"],
     ["Helpers", "For some foliar products, ingredients that aid mixing and spreading", "Only where the grade and use call for them"]])),
  ("actives", "How the active is made", "<p>The process used for the active changes the product. Humic acid is usually extracted from a humic source under alkaline conditions, which gives a soluble humate. Seaweed extracts can be made by different extraction methods and from different species, and each gives a different composition. Protein hydrolysates and amino acids are made by breaking protein down with acid, alkali or enzymes, and the method changes the mix of amino acids and peptides.</p><p>This is why two products with the same percentage on the label can behave differently: the percentage describes the content, not the process behind it.</p>"),
  ("ph", "Why pH is central", "<p>For a humic liquid, pH is the first thing a formulator controls. Humates stay in solution in alkaline conditions and can precipitate if mixed into something acidic or very hard water. That is why a mixing check matters before a humic product goes into a tank with other inputs. See our guide on <a href=\"/resources/can-humic-acid-be-mixed-with-fertilizers-and-pesticides\">mixing humic acid with fertilizers and pesticides</a>.</p>"),
  ("checks", "What a formulator checks", ul(["Active content against the grade", "pH and density", "Appearance, colour and odour", "Insoluble sediment", "Behaviour over time and at higher storage temperatures", "Mixing with common fertilizers and crop protection products"], "")),
  ("buyer", "What this means for a new brand", "<p>You do not have to formulate to start a brand. Work with a manufacturer that supplies a finished, tested product and shares the specification and test report. Ask what is checked on every batch, not only what is on the label. If you want a product adapted within a listed grade, see <a href=\"/custom-biostimulant-formulation-development\">custom formulation development</a>.</p>")],
 [("What is a biostimulant formulation?", "The finished product: an active ingredient made stable and ready to apply, in liquid, powder or granule form."),
  ("What are the ingredients of a biostimulant?", "An active such as humic acid, seaweed extract or amino acid, a base or carrier, pH control and, for liquids, protection against spoilage."),
  ("Why does pH matter in a humic acid liquid?", "Humic acid stays dissolved in alkaline conditions and can drop out of solution if the pH falls, so pH control keeps the liquid stable."),
  ("Can a new brand formulate its own biostimulant?", "Many brands buy finished formulations instead. In India a biostimulant must be a Schedule VI listed grade, so a new composition cannot simply be sold as a biostimulant."),
  ("Do you share your formulation?", "We supply the finished product with a specification sheet and test reports. We do not hand over our recipe or process.")],
 _RL + [("/resources/biostimulant-formulation-stability-shelf-life-testing", "Stability and shelf-life testing", "")],
 "how biostimulants are formulated", ["biostimulant formulation", "biostimulant ingredients", "liquid biostimulant formulation", "humic acid liquid formulation", "biostimulant manufacturing process"], "Brand owners, new entrepreneurs")

# F2 -----------------------------------------------------------------
art("liquid-vs-powder-vs-granule-biostimulants", "Liquid vs powder vs granule biostimulants: which form should you sell?", "Liquid vs Powder vs Granule Biostimulants: Which to Sell?",
 "Compare the three biostimulant forms on handling, dose, customer and cost to find the right one for your brand or your crops.",
 "Liquids suit foliar sprays, drip and drench and are easy to dose. Powders are concentrated, light to ship and dissolve into liquids or blend into fertilizers. Granules are broadcast with basal fertilizer, need no tank and suit field crops sold through dealers. The right form depends on how your customers apply products and how you want to ship and store them.",
 [("compare", "Side by side", table(["", "Liquid", "Powder", "Granule"], [
     ["How it is applied", "Spray, drip or drench", "Dissolved, or blended into fertilizer", "Broadcast or banded"],
     ["Customer", "Orchards, vegetables, drip growers", "Brands that make liquids, blenders", "Field crops, sugarcane, banana, potato, dealers"],
     ["Handling", "Needs clean packs and tank mixing", "Light, compact, dust to manage", "Easy to spread, low dust if well made"],
     ["Shipping", "Heavier because of water", "Lightest per unit of active", "Moderate"],
     ["Shelf-life concern", "Stability and spoilage", "Moisture pick-up", "Moisture and caking"]])),
  ("choose", "How to choose", ul(["<strong>Sell to drip and orchard growers?</strong> Liquids.", "<strong>Sell through dealers to field-crop farmers?</strong> Granules.", "<strong>Make your own liquids or blends?</strong> Powders as the raw material.", "<strong>Export?</strong> Powders and granules ship lighter than liquids, and a destination may prefer one form."], "")),
  ("grades", "Grades by form", "<p>The same active can be supplied in more than one form: for example humic acid as a liquid, a powder and a granule. Each is its own listed grade, and the form is part of the grade name. Browse <a href=\"/humic-acid-manufacturer-india\">humic acid</a>, <a href=\"/seaweed-extract-manufacturer-india\">seaweed extract</a> and <a href=\"/granular-biostimulants-manufacturer-india\">granules</a>.</p>"),
  ("brand", "A simple starter range", "<p>Many new brands start with one liquid for spraying and one granule for broadcast, then add a second active as dealers ask. Start with what your customers already know how to apply.</p>")],
 [("What is the difference between liquid and granular biostimulants?", "Liquids are sprayed or applied through irrigation. Granules are broadcast or banded with fertilizer and need no mixing."),
  ("Which biostimulant form is best?", "It depends on how your customers apply products. Liquids suit drip and foliar use, granules suit field crops."),
  ("Which form is cheapest to ship?", "Powders carry the most active per kilogram, so they are usually the lightest to ship."),
  ("Can one active come in all three forms?", "Often, yes. Humic acid, for example, is available as a liquid, powder and granule, each a separate listed grade.")],
 _RL + [("/granular-biostimulants-manufacturer-india", "Biostimulant granules", ""), ("/resources/slow-release-vs-water-soluble-fertilizer", "Slow-release vs water-soluble", "")],
 "liquid vs granular biostimulants", ["liquid vs powder biostimulant", "granular biostimulant", "biostimulant forms", "powder biostimulant", "biostimulant for broadcast"], "Brand owners, distributors")

# F3 -----------------------------------------------------------------
art("biostimulant-formulation-stability-shelf-life-testing", "Biostimulant stability and shelf-life testing: what to ask a manufacturer", "Biostimulant Stability & Shelf-Life Testing: What to Ask",
 "How the stability of a biostimulant is checked, what can go wrong in a liquid, powder or granule, and the questions to put to a manufacturer before you buy.",
 "Stability testing checks that a biostimulant keeps its appearance, pH and active content over time and under storage stress such as heat. For a liquid, the common failures are sediment, separation, colour or smell change and spoilage. For powders and granules they are moisture pick-up and caking. Ask any manufacturer how they test and for the batch specification.",
 [("liquid", "What can go wrong in a liquid", ul(["Sediment or a layer at the bottom of the pack", "Separation, cloudiness or colour change", "A change in pH", "Spoilage or smell in organic liquids", "Pressure or swelling in the pack"], "")),
  ("solid", "What can go wrong in a powder or granule", ul(["Moisture pick-up and caking", "Dust and broken granules", "Colour change from damp", "Uneven size that spreads badly"], "")),
  ("tests", "How stability is checked", "<p>A formulator checks the product when it is made and again over time, and also stores samples at higher temperatures to see how they hold up. Appearance, pH, density and sediment are the everyday checks. Mixing with common fertilizers and crop protection products is checked separately. The details vary by product and manufacturer, so ask for what they do on their own batches.</p>"),
  ("ask", "Questions to ask a manufacturer", ul(["How do you test stability, and for how long?", "What do you check on every batch?", "What is the shelf life and storage advice for this grade?", "Can I have the specification sheet and a recent third-party test report?", "How are packs filled and sealed?", "Is the grade a Schedule VI listed grade?"], "")),
  ("you", "What you can do on your side", ul(["Store in a cool, shaded, dry place", "Keep packs sealed and off damp floors", "Use oldest stock first and keep batch numbers", "Check a retained sample from every batch", "Report problems with the batch number so it can be traced"], ""))],
 [("How is the shelf life of a biostimulant decided?", "By checking appearance, pH and active content over time, including under higher storage temperatures, and setting the shelf life from the results."),
  ("Why does my humic acid liquid have sediment?", "Sediment can come from a pH shift, very hard water used in dilution, cold storage or the product reacting with something acidic. Send the batch number so the cause can be traced."),
  ("How long does a liquid biostimulant last?", "It depends on the grade and storage. The specification sheet for the batch gives the shelf life."),
  ("What documents should a manufacturer provide?", "A specification sheet and a recent test report, plus the NOC copy for the grade.")],
 _RL + [("/resources/how-biostimulants-are-formulated", "How biostimulants are formulated", ""), ("/quality-compliance", "Quality and compliance", "")],
 "biostimulant shelf life", ["biostimulant stability testing", "liquid biostimulant shelf life", "humic acid sediment", "biostimulant storage", "biostimulant quality control"], "Brand owners, buyers")

# F4 -----------------------------------------------------------------
art("biostimulant-business-models-compared", "Biostimulant business models compared: trade, private label, contract and own plant", "Biostimulant Business Models: Trade, Private Label, Own Plant",
 "Four ways to build a biostimulant business in India and what each one needs in time, capital, compliance and control, so you can pick the model that fits you.",
 "There are four ways into the biostimulant business: trade a finished brand, launch private label, commission contract or custom manufacturing, or build your own plant. Trading is the fastest and lightest. Private label gives you your own brand without a factory. Contract manufacturing suits a specific product idea. An own plant gives full control but takes the most time, capital and compliance work.",
 [("models", "The four models", table(["Model", "You own", "Manufacturer owns", "Speed"], [
     ["Trade a finished brand", "Sales and relationships", "Brand, product and compliance", "Fastest"],
     ["Private label", "Brand, label, marketing, customers", "Formulation, production and quality checks", "Fast: about one week after approval"],
     ["Contract or custom manufacturing", "The product idea and brand", "Development and production", "Slower: lab work and trial first"],
     ["Own plant", "Everything", "Nothing", "Slowest"]])),
  ("pick", "Which one suits you", ul(["<strong>Agri-input shop or distributor:</strong> start with trade, then move to private label.", "<strong>New brand with a market:</strong> private label.", "<strong>Specific crop programme or export idea:</strong> contract or custom manufacturing.", "<strong>Large long-term player:</strong> own plant, after you have proven demand."], "")),
  ("compliance", "What the rules mean for each", "<p>In India every route needs the biostimulant to be a Schedule VI listed grade and the seller to hold the state authorisation to sell. With trade, the brand owner usually carries the grade and authorisation. With private label you need your own authorisation to sell under your name, and the manufacturer supplies the listed grade and documents. An own plant adds manufacturing approvals and a quality system. Check current requirements with your state agriculture department.</p>"),
  ("grow", "A common path", "<p>Many brands start with a small private-label range, learn what dealers and growers ask for, and add grades and pack sizes. Some later commission custom products for a crop programme. An own plant is usually considered only after demand is proven.</p>")],
 [("What is the easiest way to start a biostimulant business?", "Trading a finished brand is the lightest route, and private label gives you your own brand without a factory."),
  ("Is private label better than building my own plant?", "For most new brands, yes: it needs far less time and capital, and you can test a market with a small first order. An own plant makes sense after demand is proven."),
  ("Do I need a licence for private label?", "You need the state authorisation to sell fertilizers and biostimulants under your name, and the product must be a Schedule VI listed grade. Check with your state department."),
  ("What is contract manufacturing?", "A manufacturer makes a product to your brief and specification. In India that means within listed grades.")],
 _RL + [("/private-label-oem", "Private label", ""), ("/custom-biostimulant-formulation-development", "Custom formulation", "")],
 "biostimulant business models", ["private label vs contract manufacturing", "start biostimulant manufacturing business", "own fertilizer plant vs private label", "third party fertilizer manufacturing"], "Entrepreneurs, brand owners")

# F5 -----------------------------------------------------------------
art("biostimulant-label-and-documents-checklist", "Biostimulant label and documents checklist for a new brand", "Biostimulant Label & Documents Checklist for New Brands",
 "A practical checklist of what a new biostimulant brand should have on the label and on file before it sells, and the documents to ask a manufacturer for.",
 "Before a new brand sells a biostimulant in India, the grade on the label should match a Schedule VI listed grade, the seller should hold the state authorisation to sell, and the label should carry the details the rules require. Ask the manufacturer for a specification sheet, the NOC copy and a recent test report. Check the exact label requirements with your state agriculture department.",
 [("label", "What a label usually needs", ul(["The exact grade name and concentration", "Net quantity and pack size", "Batch number, manufacturing date and expiry or shelf life", "Manufacturer and marketer name and address", "Directions for use, dose and precautions", "Storage advice", "Your authorisation or licence details, as your state requires"], "") + "<p>Rules and wording change, so confirm the exact requirements with your state agriculture department before you print.</p>"),
  ("docs", "Documents to ask the manufacturer for", ul(["Specification sheet for the grade and batch", "Copy of the NOC or approval covering the grade", "A recent third-party test report", "Safety information and storage advice", "Batch records so every pack can be traced"], "")),
  ("claims", "Keep claims honest", "<p>Describe what the product is, what it contains and how to apply it. Avoid promises about yield or income. Results vary with crop, soil, weather and practice, so share grower experiences as individual experiences, not product promises.</p>"),
  ("mistakes", "Common mistakes", ul(["A grade name on the label that is not a listed grade", "Printing labels before the authorisation is in place", "No batch number, so a complaint cannot be traced", "Copying another brand's claims", "Choosing a pack size dealers do not buy"], ""))],
 [("What must be on a biostimulant label in India?", "The grade name and concentration, quantity, batch number, dates, manufacturer details, directions for use and your authorisation details, as the rules require. Confirm the exact list with your state agriculture department."),
  ("Which documents should a manufacturer give a private-label brand?", "A specification sheet, the NOC copy and a recent test report, plus batch details."),
  ("Can I put my brand name on a biostimulant made by someone else?", "Yes, through private label, if you hold the authorisation to sell and the label meets the rules."),
  ("Can I make yield claims on the label?", "Avoid them. Describe the product and how to use it, and note that results vary.")],
 _RL + [("/fco-schedule-vi-biostimulants", "FCO Schedule VI", ""), ("/resources/how-to-start-a-fertilizer-brand-private-label", "How to start a fertilizer brand", "")],
 "biostimulant label requirements", ["biostimulant documents checklist", "fertilizer label requirements india", "private label fertilizer documents", "biostimulant packaging label"], "Brand owners, new entrepreneurs")

# F6 -----------------------------------------------------------------
art("biostimulant-blends-humic-seaweed-amino-acid", "Biostimulant blends: humic, seaweed and amino acid combinations explained", "Biostimulant Blends: Humic, Seaweed & Amino Acid Explained",
 "Why brands combine humic acid, seaweed extract and amino acids, what each part is for, and what to check on compatibility and the listed grade.",
 "Brands blend humic acid, seaweed extract and amino acids because each acts differently: humic acid conditions the root zone, seaweed extracts are used for growth support and stress periods, and amino acids are used when a crop needs a quick lift. A blend must still be a listed grade for India, and its parts must stay stable together, so compatibility is checked before it is sold.",
 [("roles", "What each part is used for", table(["Part", "Common use", "Where it fits"], [
     ["Humic acid", "Soil and root-zone conditioning", "Soil application, drip and basal use"],
     ["Seaweed extract", "Growth support and stress periods", "Foliar and soil use"],
     ["Amino acid or protein hydrolysate", "Support at key stages and after stress", "Foliar and drip"]])),
  ("why", "Why brands blend", ul(["One product covers more than one use, so the dealer has less to stock", "Simpler programmes for the grower", "A product that is easier to position than three separate ones"], "")),
  ("watch", "What to watch", ul(["<strong>Listed grade.</strong> In India the blend should match a listed grade, such as humic acid with seaweed extract. Do not invent a blend and sell it as a biostimulant.", "<strong>Compatibility.</strong> Humic acid needs alkaline conditions and can drop out of a mix that is too acidic.", "<strong>Dose.</strong> A blend has a different dose from its parts. Follow the label.", "<strong>Claims.</strong> Describe each part by what it is, not by promised results."], "")),
  ("ours", "Blends we make", "<p>We make humic acid with seaweed extract as a listed grade, in granule form and others. See the <a href=\"/products/humic-acid-plus-seaweed-extract-granules\">humic + seaweed granules</a>, our <a href=\"/granular-biostimulants-manufacturer-india\">granules range</a> and <a href=\"/custom-biostimulant-formulation-development\">custom formulation within listed grades</a>.</p>")],
 [("Can I mix humic acid and seaweed extract?", "Yes, as a manufactured, tested blend. A mix made on the farm should be checked for compatibility first."),
  ("Is a humic and seaweed blend a listed biostimulant grade?", "Humic acid with seaweed extract is a grade we hold under our Gujarat NOC. Check any blend against Schedule VI before you sell it."),
  ("Why combine amino acids with seaweed extract?", "They are used for different purposes, so brands combine them to offer one product for more than one use."),
  ("Can you make a custom blend?", "Within listed grades and the rules of your market, yes. Send your brief.")],
 _RL + [("/resources/humic-vs-seaweed-granules", "Humic vs seaweed granules", ""), ("/resources/seaweed-extract-uses-in-agriculture", "Seaweed extract uses", "")],
 "biostimulant blends", ["humic and seaweed blend", "seaweed amino acid blend", "combination biostimulant", "multi active biostimulant", "humic acid seaweed extract mixture"], "Brand owners, distributors")
